    'concept_book_beauty_now' => 'Book.<br><span>Beauty.</span><br>Now.',
    'concept_book_beauty_now_desc' => 'ಅನಗತ್ಯವಿಲ್ಲ. ಅರ್ಥವಿಲ್ಲದ ಮಾತಿಲ್ಲ. ಅತ್ಯುತ್ತಮ ಸಲೂನ್‌ಗಳು, ತಕ್ಷಣವೇ ಬುಕ್ ಮಾಡಬಹುದಾದವು. ಅಷ್ಟೆ.',
    'concept_natural_beauty' => 'ನೈಸರ್ಗಿಕ ಸೌಂದರ್ಯ,<br>ಸಹಜವಾಗಿ ಬುಕ್ ಆಗಿದೆ',
    'concept_natural_beauty_desc' => 'ನಿಮ್ಮ ಮತ್ತು ಭೂಮಿಯ ಬಗ್ಗೆ ಕಾಳಜಿ ವಹಿಸುವ ಪರಿಸರ ಜಾಗೃತ ಸಲೂನ್‌ಗಳೊಂದಿಗೆ ಸಂಪರ್ಕ ಹೊಂದಿ. ಸುಸ್ಥಿರ ಸೌಂದರ್ಯ ಇಲ್ಲಿ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.',
    'concept_art_of_beauty' => 'ಸೌಂದರ್ಯದ<br>ಕಲೆ',
    'concept_art_of_beauty_desc' => 'ಅತ್ಯುತ್ತಮ ಸಂಸ್ಥೆಗಳಲ್ಲಿ ವಿಶೇಷ ಸೌಂದರ್ಯ ಸೇವೆಗಳನ್ನು ಅನುಭವಿಸಿ. ಐಷಾರಾಮ ಮತ್ತು ಪರಿಪೂರ್ಣತೆ ಭೇಟಿಯಾಗುವ ಸ್ಥಳ.',
