    'concept_beauty_shines' => 'ಪ್ರಕಾಶಮಾನವಾಗಿ<br>ಹೊಳೆಯುವ ಸೌಂದರ್ಯ',
    'concept_beauty_shines_desc' => 'ಅತ್ಯುತ್ತಮ ವೃತ್ತಿಪರರಿಂದ ಅಸಾಧಾರಣ ಸೌಂದರ್ಯ ಸೇವೆಗಳನ್ನು ಅನ್ವೇಷಿಸಿ. ನಿಮ್ಮ ಪರಿಪೂರ್ಣ ನೋಟ ಒಂದು ಕ್ಲಿಕ್ ದೂರದಲ್ಲಿದೆ.',
    'concept_natural_elevated' => 'ನೈಸರ್ಗಿಕ ಸೌಂದರ್ಯ,<br><span>ಉನ್ನತೀಕರಿಸಲಾಗಿದೆ.</span>',
