    'platform_fee_info_desc' => 'ನಗದು ಪಾವತಿಗಳಿಗೆ, ಗ್ರಾಹಕರು ಬುಕಿಂಗ್ ಸಮಯದಲ್ಲಿ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕವನ್ನು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಪಾವತಿಸುತ್ತಾರೆ. ಈ ಮೊತ್ತವನ್ನು ನಿಮ್ಮ ಬಾಕಿ ಇರುವ ನಗದು ಬ್ಯಾಲೆನ್ಸ್‌ನಿಂದ ಕಡಿತಗೊಳಿಸಲಾಗುತ್ತದೆ.',
